{"content":"import json
from copy import deepcopy


class RestAPI:
    def __init__(self, database=None):
        self.database = deepcopy(database) if database is not None else {"users": []}

    def get(self, url, payload=None):
        if url != "/users":
            raise ValueError("Unknown GET endpoint: " + url)

        users = self.database["users"]
        if payload is not None:
            requested = json.loads(payload).get("users")
            if requested is not None:
                users = [user for user in users if user["name"] in requested]
        return json.dumps({"users": sorted(users, key=lambda user: user["name"])})

    def post(self, url, payload=None):
        if url not in ("/add", "/iou"):
            raise ValueError("Unknown POST endpoint: " + url)
        if payload is None:
            raise ValueError("POST requests require a JSON payload")
        data = json.loads(payload)

        if url == "/add":
            name = data["user"]
            if any(user["name"] == name for user in self.database["users"]):
                raise ValueError("User already exists: " + name)
            user = {"name": name, "owes": {}, "owed_by": {}, "balance": 0.0}
            self.database["users"].append(user)
            return json.dumps(user)

        users = {user["name"]: user for user in self.database["users"]}
        lender = users[data["lender"]]
        borrower = users[data["borrower"]]
        amount = data["amount"]
        if lender is borrower:
            raise ValueError("Lender and borrower must be different users")
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise ValueError("Amount must be a number")
        if not 0 <= amount < float("inf"):
            raise ValueError("Amount must be finite and nonnegative")

        lender_name, borrower_name = lender["name"], borrower["name"]
        # A positive net means the borrower owes the lender. Opposite debts
        # cancel, so each pair has at most one outstanding direction.
        net = (
            lender["owed_by"].get(borrower_name, 0.0)
            - lender["owes"].get(borrower_name, 0.0)
            + amount
        )
        for user, other_name in ((lender, borrower_name), (borrower, lender_name)):
            user["owes"].pop(other_name, None)
            user["owed_by"].pop(other_name, None)

        if net > 0:
            lender["owed_by"][borrower_name] = net
            borrower["owes"][lender_name] = net
        elif net < 0:
            lender["owes"][borrower_name] = -net
            borrower["owed_by"][lender_name] = -net

        for user in (lender, borrower):
            user["balance"] = sum(user["owed_by"].values()) - sum(user["owes"].values())

        return json.dumps({"users": sorted((lender, borrower), key=lambda user: user["name"])})
