import unittest

from rest_api import RestAPI


def user(name, owes=None, owed_by=None):
    owes = {} if owes is None else owes
    owed_by = {} if owed_by is None else owed_by
    return {
        "name": name,
        "owes": owes,
        "owed_by": owed_by,
        "balance": sum(owed_by.values()) - sum(owes.values()),
    }


class RestAPITest(unittest.TestCase):
    def iou(self, api, lender, borrower, amount):
        return json.loads(api.post("/iou", json.dumps({
            "lender": lender, "borrower": borrower, "amount": amount,
        })))

    def test_empty_database(self):
        self.assertEqual(json.loads(RestAPI().get("/users")), {"users": []})

    def test_add_user_and_persist(self):
        api = RestAPI()
        self.assertEqual(json.loads(api.post("/add", '{"user":"Adam"}')), user("Adam"))
        self.assertEqual(json.loads(api.get("/users")), {"users": [user("Adam")]})
        self.assertEqual(json.loads(RestAPI().get("/users")), {"users": []})

    def test_list_and_filter_sorted(self):
        api = RestAPI({"users": [user("Dan"), user("Bob"), user("Adam")]})
        self.assertEqual(json.loads(api.get("/users")), {
            "users": [user("Adam"), user("Bob"), user("Dan")],
        })
        self.assertEqual(json.loads(api.get("/users", '{"users":["Dan","Adam"]}')), {
            "users": [user("Adam"), user("Dan")],
        })
        self.assertEqual(json.loads(api.get("/users", '{"users":[]}')), {"users": []})

    def test_new_and_repeated_iou(self):
        api = RestAPI({"users": [user("Bob"), user("Adam")]})
        self.assertEqual(self.iou(api, "Bob", "Adam", 5.25), {"users": [
            user("Adam", owes={"Bob": 5.25}),
            user("Bob", owed_by={"Adam": 5.25}),
        ]})
        expected = {"users": [
            user("Adam", owes={"Bob": 7.5}),
            user("Bob", owed_by={"Adam": 7.5}),
        ]}
        self.assertEqual(self.iou(api, "Bob", "Adam", 2.25), expected)
        self.assertEqual(json.loads(api.get("/users")), expected)

    def test_opposite_iou_reduces_clears_or_reverses_debt(self):
        for amount, remaining in ((3, 7), (10, 0), (12.5, -2.5)):
            with self.subTest(amount=amount):
                api = RestAPI({"users": [
                    user("Adam", owes={"Bob": 10}),
                    user("Bob", owed_by={"Adam": 10}),
                ]})
                if remaining > 0:
                    expected = [user("Adam", owes={"Bob": remaining}),
                                user("Bob", owed_by={"Adam": remaining})]
                elif remaining < 0:
                    expected = [user("Adam", owed_by={"Bob": -remaining}),
                                user("Bob", owes={"Adam": -remaining})]
                else:
                    expected = [user("Adam"), user("Bob")]
                self.assertEqual(self.iou(api, "Adam", "Bob", amount), {"users": expected})

    def test_other_debts_unchanged_and_input_not_mutated(self):
        database = {"users": [
            user("Adam", owes={"Chuck": 4}),
            user("Bob"),
            user("Chuck", owed_by={"Adam": 4}),
        ]}
        original = json.dumps(database)
        api = RestAPI(database)
        self.assertEqual(self.iou(api, "Adam", "Bob", 5.25), {"users": [
            user("Adam", owes={"Chuck": 4}, owed_by={"Bob": 5.25}),
            user("Bob", owes={"Adam": 5.25}),
        ]})
        self.assertEqual(json.loads(api.get("/users", '{"users":["Chuck"]}')), {
            "users": [user("Chuck", owed_by={"Adam": 4})],
        })
        self.assertEqual(json.dumps(database), original)

    def test_zero_iou_creates_no_debt_entries(self):
        api = RestAPI({"users": [user("Adam"), user("Bob")]})
        self.assertEqual(self.iou(api, "Adam", "Bob", 0), {
            "users": [user("Adam"), user("Bob")],
        })

    def test_invalid_requests_do_not_mutate_database(self):
        api = RestAPI({"users": [user("Adam"), user("Bob")]})
        original = api.get("/users")
        for amount in (-1, float("inf"), float("nan"), True, "5"):
            with self.subTest(amount=amount), self.assertRaises(ValueError):
                self.iou(api, "Adam", "Bob", amount)
        with self.assertRaises(ValueError):
            self.iou(api, "Adam", "Adam", 5)
        with self.assertRaises(KeyError):
            self.iou(api, "Adam", "Unknown", 5)
        with self.assertRaises(ValueError):
            api.post("/add", '{"user":"Adam"}')
        with self.assertRaises(ValueError):
            api.post("/add")
        with self.assertRaises(ValueError):
            api.get("/unknown")
        with self.assertRaises(ValueError):
            api.post("/unknown", "{}")
        self.assertEqual(api.get("/users"), original)


if __name__ == "__main__":
    unittest.main()
